from pathlib import Path
import json,pandas as pd
def load_performance(root):
 root=Path(root);r=root/'results';cv=json.loads((r/'v11_2_cv_metrics.json').read_text());comp=pd.read_csv(r/'v11_2_untouched_2025_comparison.csv').set_index('model').loc['V11_2_compact'];eff=pd.read_csv(r/'v11_2_computational_efficiency.csv').set_index('feature_count');overall=pd.read_csv(r/'v11_2_confidence_overall_diagnostics.csv').set_index('scope').loc['combined'];levels=pd.read_csv(r/'v11_2_confidence_cumulative_levels.csv');high=levels[(levels.measure.eq('favorite_probability'))&levels.threshold.eq(.6)&levels.scope.eq('combined')].iloc[0];season=levels[(levels.measure.eq('favorite_probability'))&levels.threshold.eq(.6)&levels.scope.ne('combined')][['scope','games','accuracy']].to_dict('records')
 return {'data':{'games':cv['historical_games_processed'],'team_games':cv['team_game_observations'],'pitcher_games':cv['official_pitcher_game_records']},'efficiency':{'original':cv['original_feature_count'],'compact':cv['compact_feature_count'],'feature_reduction_pct':cv['feature_reduction_pct'],'training_reduction_pct':1-eff.loc[50,'training_time_relative'],'prediction_reduction_pct':1-eff.loc[50,'prediction_time_relative'],'memory_reduction_pct':1-eff.loc[50,'peak_memory_mb']/eff.loc[173,'peak_memory_mb']},'forecast':{'rmse':comp.rmse,'mae':comp.mae,'game_total_rmse':comp.game_total_rmse,'winner_auc':comp.winner_auc,'winner_accuracy':comp.winner_accuracy},'confidence':{'oos_games':int(overall.games),'overall_accuracy':overall.accuracy,'high_games':int(high.games),'high_accuracy':high.accuracy,'ci_low':high.accuracy_ci_low,'ci_high':high.accuracy_ci_high,'seasonal':season}}

